WITH with_windows AS (SELECT id, supplier_name, rating, NTILE(4) OVER (ORDER BY rating DESC, id) AS rating_bucket, SUM(rating) OVER (ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_rating FROM suppliers), enriched AS (SELECT id, supplier_name, running_rating, LEAD(running_rating, 2) OVER (ORDER BY running_rating, id) AS next_running_rating, NTILE(10) OVER (ORDER BY rating_bucket, id) AS rating_bucket_bucket, AVG(running_rating) OVER (ORDER BY rating, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS running_rating_avg_5_prior FROM with_windows), with_last AS (SELECT s.*, top1.launch_date FROM enriched s JOIN LATERAL (SELECT c.launch_date FROM products c WHERE c.supplier_id = s.id ORDER BY c.launch_date DESC, c.id DESC LIMIT 1) top1 ON TRUE), enriched_suppliers AS (SELECT *, LEAD(rating_bucket_bucket, 1) OVER (ORDER BY rating_bucket_bucket, id) AS next_rating_bucket_bucket, LAG(running_rating, 2) OVER (ORDER BY launch_date, id) AS prev_running_rating, CUME_DIST() OVER (ORDER BY next_running_rating DESC) AS next_running_rating_cume_dist, DENSE_RANK() OVER (ORDER BY next_running_rating DESC) AS next_running_rating_dense_rank FROM with_last WHERE LENGTH(supplier_name) >= 11), not_flagged AS (SELECT s.* FROM enriched_suppliers s WHERE NOT EXISTS (SELECT 1 FROM products x WHERE x.supplier_id = s.id AND x.launch_date <= s.launch_date)), not_flagged_suppliers AS (SELECT s.* FROM not_flagged s WHERE NOT EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.brand = 'Umbrella')), summary AS (SELECT DATE_TRUNC('QUARTER', launch_date) AS quarter_start, PERCENTILE_APPROX(next_running_rating_dense_rank, ARRAY(0.25, 0.5, 0.75)) AS next_running_rating_dense_rank_quartiles, SUM(next_running_rating_dense_rank) AS total_next_running_rating_dense_rank, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT id) AS distinct_ids_2, PERCENTILE_APPROX(next_running_rating, 0.95) AS next_running_rating_p95 FROM not_flagged_suppliers GROUP BY ROLLUP (DATE_TRUNC('QUARTER', launch_date))) SELECT quarter_start, next_running_rating_p95 FROM summary ORDER BY next_running_rating_p95 DESC NULLS LAST, quarter_start;
